#include <iostream>
#include <vector>
#include <queue>
#include <string>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;

struct MaxFlow {
    struct Edge {
        int dest;
        int back;
        ll cap;
    };

    vector<vector<Edge>> adj;
    vector<int> dist, cur;
    int source, target;

    MaxFlow(int n, int s, int t) : adj(n), dist(n), cur(n), source(s), target(t) {}

    void connect(int u, int v, ll c) {
        adj[u].push_back({v, (int)adj[v].size(), c});
        adj[v].push_back({u, (int)adj[u].size()-1, 0});
    }

    bool levelGraph() {
        fill(dist.begin(), dist.end(), -1);
        dist[source] = 0;
        queue<int> q;
        q.push(source);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &e : adj[u]) {
                if (e.cap > 0 && dist[e.dest] == -1) {
                    dist[e.dest] = dist[u] + 1;
                    q.push(e.dest);
                }
            }
        }
        return dist[target] != -1;
    }

    ll blockingFlow(int u, ll flow) {
        if (u == target) return flow;
        for (int &i = cur[u]; i < (int)adj[u].size(); ++i) {
            Edge &e = adj[u][i];
            if (e.cap > 0 && dist[e.dest] == dist[u] + 1) {
                ll pushed = blockingFlow(e.dest, min(flow, e.cap));
                if (pushed > 0) {
                    e.cap -= pushed;
                    adj[e.dest][e.back].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll solve() {
        ll result = 0;
        while (levelGraph()) {
            fill(cur.begin(), cur.end(), 0);
            ll pushed;
            while ((pushed = blockingFlow(source, 1e18)) > 0) {
                result += pushed;
            }
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, T;
    cin >> n >> T;

    vector<string> grid(n);
    int zy = -1, zx = -1;
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                zy = i; zx = j;
            }
        }
    }

    string dummy;
    getline(cin, dummy);
    getline(cin, dummy);

    vector<string> exits(n);
    for (int i = 0; i < n; ++i) {
        cin >> exits[i];
    }

    vector<vector<int>> timeLimit(n, vector<int>(n, -1));
    queue<pair<int, int>> q;
    q.push({zy, zx});
    timeLimit[zy][zx] = 0;

    const int dy[] = {1, -1, 0, 0};
    const int dx[] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto [y, x] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dy[d], nx = x + dx[d];
            if (ny < 0 || ny >= n || nx < 0 || nx >= n) continue;
            if (timeLimit[ny][nx] != -1 || grid[ny][nx] == 'Y') continue;
            timeLimit[ny][nx] = timeLimit[y][x] + 1;
            if (timeLimit[ny][nx] < T) {
                q.push({ny, nx});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                if (timeLimit[i][j] == -1) timeLimit[i][j] = T;
                else timeLimit[i][j] = min(timeLimit[i][j], T);
            }
        }
    }

    vector<vector<int>> nodeId(n, vector<int>(n, -1));
    int nodeCount = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                nodeId[i][j] = nodeCount++;
            }
            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                nodeId[i][j] = nodeCount++;
            }
        }
    }

    int src = 0, dst = nodeCount + 1;
    MaxFlow flow(nodeCount + 2, src, dst);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                flow.connect(src, nodeId[i][j], grid[i][j] - '0');
            }

            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                flow.connect(nodeId[i][j], dst, exits[i][j] - '0');
            }

            for (int d = 0; d < 4; ++d) {
                int ni = i + dy[d], nj = j + dx[d];
                if (ni < 0 || ni >= n || nj < 0 || nj >= n) continue;
                if (grid[ni][nj] == 'Y' || grid[ni][nj] == 'Z') continue;

                if (nodeId[i][j] != -1 && nodeId[ni][nj] != -1) {
                    flow.connect(nodeId[i][j], nodeId[ni][nj], 1000000000);
                }
            }
        }
    }

    cout << flow.solve() << '\n';
    return 0;
}
